DROP TABLE IF EXISTS `number_translations`;
CREATE TABLE `number_translations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL,
  `pattern` varchar(200) CHARACTER SET latin1 COLLATE latin1_general_ci DEFAULT '$1',
  `replace` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `accountid` int DEFAULT '0',
  `description` varchar(255) DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT '0',
  `creation_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `last_modified_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;




INSERT INTO `number_translations` VALUES (1,'internal_4','^[2-9](\\d{4})','$1',0,NULL,0,'2024-10-13 05:22:30','2024-10-13 05:22:36'),(2,'internal_3','^[2-9](\\d{3})','$1',0,NULL,0,'2024-10-13 05:22:30','2024-10-13 05:22:36'),(3,'inbound_4','^[1-9][1-9]\\d{4}(\\d+)$','$1',0,NULL,0,'2024-10-13 05:22:30','2024-10-13 05:22:36'),(4,'inbound_3','^[1-9][1-9]\\d{5}(\\d+)$','$1',0,NULL,0,'2024-10-13 05:22:30','2024-10-13 05:22:36');



DROP TABLE IF EXISTS `numbers_translations`;
CREATE TABLE `numbers_translations` (
  `id` int NOT NULL AUTO_INCREMENT,
  `translation_name` varchar(80) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `account_id` int NOT NULL DEFAULT '0',
  `reseller_id` int NOT NULL DEFAULT '0',
  `status` tinyint(1) DEFAULT NULL COMMENT '0:active,1:inactive',
  `translation_description` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '',
  `creation_date` datetime DEFAULT NULL,
  `last_modified_date` datetime DEFAULT '1000-01-01 00:00:00' ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;


