DROP VIEW IF EXISTS `translations_details`;

CREATE ALGORITHM=UNDEFINED DEFINER=`fluxuser`@`127.0.0.1` SQL SECURITY DEFINER VIEW `translations_details` AS select `numbers_translations`.`id` AS `id`,`numbers_translations`.`translation_name` AS `translation_name`,concat('"',group_concat(`number_translation_details`.`translation_detail_regex` separator ','),'"') AS `regex`,concat('"',group_concat(`number_translation_details`.`translation_detail_replace` separator ','),'"') AS `replace` from (`numbers_translations` left join `number_translation_details` on((`numbers_translations`.`id` = `number_translation_details`.`translation_id`))) group by `numbers_translations`.`id`;